{
  "story": "Alice locks a secret message inside a box using a public key. Only Bob possesses the private key required to unlock it.",
  "aha": {
    "stateId": "decrypt",
    "observation": "The private key successfully unlocks the message encrypted by the matching public key."
  },
  "layout": {
    "preset": "stepper-card",
    "width": 640
  },
  "parts": [
    {
      "id": "rail",
      "kind": "step-rail",
      "bind": {
        "active": "inputs.stepIndex",
        "items": "variant.states"
      }
    },
    {
      "id": "picture",
      "kind": "fixed-picture",
      "bind": {
        "active": "inputs.stepIndex",
        "regions": "variant.regions",
        "values": "variant.states"
      }
    },
    {
      "id": "callout",
      "kind": "active-callout",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "readout",
      "kind": "value-readout",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "stepIndex",
      "kind": "index",
      "label": "Step",
      "options": [
        "Generate",
        "Encrypt",
        "Decrypt"
      ]
    },
    {
      "id": "resetBtn",
      "kind": "reset",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "RSA Overview",
        "regions": [
          {
            "id": "pub",
            "label": "Public Key",
            "kind": "key",
            "values": ["Lock"]
          },
          {
            "id": "priv",
            "label": "Private Key",
            "kind": "key",
            "values": ["Unlock"]
          }
        ],
        "states": [
          {
            "id": "generate",
            "label": "1. Generate",
            "short": "Key pair",
            "sentence": "Bob creates a public and private key pair.",
            "why": "Setup keys",
            "active": ["pub", "priv"],
            "calloutRegion": "pub",
            "readouts": [
              {
                "id": "r1",
                "label": "Visibility",
                "value": "Public"
              }
            ]
          },
          {
            "id": "encrypt",
            "label": "2. Encrypt",
            "short": "Lock message",
            "sentence": "Alice locks the message using Bob's public key.",
            "why": "Secure in transit",
            "active": ["pub"],
            "calloutRegion": "pub",
            "readouts": [
              {
                "id": "r2",
                "label": "State",
                "value": "Ciphertext"
              }
            ]
          },
          {
            "id": "decrypt",
            "label": "3. Decrypt",
            "short": "Unlock message",
            "sentence": "Bob unlocks the ciphertext using his private key.",
            "why": "Retrieve plaintext",
            "active": ["priv"],
            "calloutRegion": "priv",
            "readouts": [
              {
                "id": "r3",
                "label": "State",
                "value": "Plaintext"
              }
            ]
          }
        ]
      }
    ]
  }
}
